create extension if not exists pgcrypto; create table if not exists public.b2b_businesses(id uuid primary key default gen_random_uuid(),legal_name text not null,trading_name text,nzbn text,verification_status text not null default 'UNVERIFIED' check(verification_status in('UNVERIFIED','PENDING','VERIFIED','SUSPENDED')),created_at timestamptz not null default now()); create table if not exists public.b2b_listings(id uuid primary key default gen_random_uuid(),seller_id uuid not null references public.b2b_businesses(id),title text not null,description text not null default '',category text not null,condition text,quantity numeric not null default 1,unit_price_nzd numeric,pricing_mode text not null default 'FIXED' check(pricing_mode in('FIXED','NEGOTIABLE','RFQ','AUCTION')),status text not null default 'DRAFT' check(status in('DRAFT','LIVE','RESERVED','SOLD','WITHDRAWN')),location text,source_evidence jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now()); create table if not exists public.b2b_rfqs(id uuid primary key default gen_random_uuid(),buyer_id uuid not null references public.b2b_businesses(id),title text not null,specification text not null,category text not null,quantity numeric,target_price_nzd numeric,delivery_location text,due_at timestamptz,status text not null default 'OPEN' check(status in('DRAFT','OPEN','QUOTED','AWARDED','CLOSED')),created_at timestamptz not null default now()); create table if not exists public.b2b_quotes(id uuid primary key default gen_random_uuid(),rfq_id uuid not null references public.b2b_rfqs(id) on delete cascade,supplier_id uuid not null references public.b2b_businesses(id),price_nzd numeric not null,lead_time_days integer,terms text,status text not null default 'SUBMITTED' check(status in('SUBMITTED','ACCEPTED','REJECTED','EXPIRED')),created_at timestamptz not null default now()); create table if not exists public.b2b_orders(id uuid primary key default gen_random_uuid(),listing_id uuid references public.b2b_listings(id),buyer_id uuid not null references public.b2b_businesses(id),seller_id uuid not null references public.b2b_businesses(id),agreed_price_nzd numeric not null,payment_status text not null default 'UNPAID' check(payment_status in('UNPAID','AUTHORIZED','SETTLED','REFUNDED')),fulfillment_status text not null default 'PENDING' check(fulfillment_status in('PENDING','IN_PROGRESS','FULFILLED','DISPUTED','CANCELLED')),verified_status text not null default 'UNVERIFIED' check(verified_status in('UNVERIFIED','VERIFIED','CONTRADICTED')),created_at timestamptz not null default now()); create index if not exists b2b_listings_category_status_idx on public.b2b_listings(category,status); create index if not exists b2b_rfqs_status_category_idx on public.b2b_rfqs(status,category); create index if not exists b2b_orders_status_idx on public.b2b_orders(payment_status,fulfillment_status,verified_status); alter table public.b2b_businesses enable row level security; alter table public.b2b_listings enable row level security; alter table public.b2b_rfqs enable row level security; alter table public.b2b_quotes enable row level security; alter table public.b2b_orders enable row level security;